import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import {
  isUntitled,
  cleanTitle,
  titleFromText,
  titleFromUrl,
  textFromBody,
  deriveTitle
} from '../../src/shared/titles'

// "Too many rooms, documents and office items, widgets and desks are untitled.
// Make it so making a title is required, where generated by AI its given, and
// where it exists elsewhere inherit the content and choose a title using a
// lowest model of ai based on its content. Super low credit usage for that
// extreme case. Retrospectively run this on start up."
//
// The free path is what makes the cheap path cheap: nearly everything can be
// named from what it already contains, and the model only sees the remainder.
// So these tests are mostly about the free path being good enough — and about
// it refusing to guess, because a confident wrong name is worse than a
// visibly missing one.

const ROOT = join(__dirname, '..', '..', 'src')
const read = (rel: string): string => readFileSync(join(ROOT, rel), 'utf8')

describe('recognising the absence of a name', () => {
  it('treats empty and whitespace as untitled', () => {
    expect(isUntitled('')).toBe(true)
    expect(isUntitled('   ')).toBe(true)
    expect(isUntitled(null)).toBe(true)
    expect(isUntitled(undefined)).toBe(true)
  })

  it('treats the UI’s own placeholders as untitled', () => {
    // These were being STORED as values, which made them indistinguishable
    // from a name the user chose.
    for (const t of [
      'Untitled',
      'Untitled desk',
      'Untitled document',
      'untitled sheet',
      'New calendar',
      'Untitled document 2',
      'New 3'
    ]) {
      expect(isUntitled(t), t).toBe(true)
    }
  })

  it('does NOT touch a real title that happens to start with those words', () => {
    // The conservative bar: a real name survives even if it opens with
    // "New" or "Untitled".
    for (const t of [
      'New hire onboarding',
      'Untitled Goose Game notes',
      'New Zealand trip',
      'New pricing page copy'
    ]) {
      expect(isUntitled(t), t).toBe(false)
    }
  })
})

describe('tidying a candidate into a name', () => {
  it('strips markdown scaffolding', () => {
    expect(cleanTitle('## Quarterly review')).toBe('Quarterly review')
    expect(cleanTitle('- [ ] Ship the thing')).toBe('Ship the thing')
    expect(cleanTitle('> A quoted opening')).toBe('A quoted opening')
    expect(cleanTitle('1. First item')).toBe('First item')
    expect(cleanTitle('**Bold** heading')).toBe('Bold heading')
    expect(cleanTitle('[Read the brief](https://x.com/b)')).toBe('Read the brief')
  })

  it('collapses whitespace and drops trailing punctuation', () => {
    expect(cleanTitle('  Spaced   out  ')).toBe('Spaced out')
    expect(cleanTitle('A heading:')).toBe('A heading')
  })

  it('cuts long text at a word boundary, never mid-word', () => {
    const long = 'Supercalifragilistic planning notes for the forthcoming quarter and beyond'
    const out = cleanTitle(long)
    expect(out.length).toBeLessThanOrEqual(60)
    expect(long.startsWith(out)).toBe(true)
    expect(out.endsWith(' ')).toBe(false)
    // The cut landed on a word boundary: the next char in the source is a space.
    expect(long[out.length]).toBe(' ')
  })
})

describe('naming from the item’s own text', () => {
  it('prefers a heading, because that is a name the user already wrote', () => {
    const body = 'Tuesday, 3pm\nby Michael\n\n# Pricing for the Q4 launch\n\nSome prose follows.'
    expect(titleFromText(body)).toBe('Pricing for the Q4 launch')
  })

  it('falls back to the first substantial line', () => {
    expect(titleFromText('Notes from the client call\nthen more detail')).toBe(
      'Notes from the client call'
    )
  })

  it('takes the first SENTENCE of a long opening paragraph', () => {
    const para =
      'We agreed to move the launch to November. The rest of this paragraph goes on at length about why.'
    expect(titleFromText(para)).toBe('We agreed to move the launch to November')
  })

  it('refuses to name from noise rather than guessing', () => {
    // Null means "try the next source", and eventually "leave it alone".
    for (const junk of ['', '   ', '---', '***', '42', 'ok', 'https://example.com/a/b']) {
      expect(titleFromText(junk), JSON.stringify(junk)).toBeNull()
    }
  })

  it('skips the junk line and uses the real one', () => {
    expect(titleFromText('---\n\nBudget approvals for March')).toBe('Budget approvals for March')
  })
})

describe('naming a link-shaped thing', () => {
  it('humanises the last path segment', () => {
    expect(titleFromUrl('https://example.com/docs/quarterly-review')).toBe('Quarterly review')
    expect(titleFromUrl('https://example.com/notes/team_standup.html')).toBe('Team standup')
  })

  it('drops a trailing id rather than naming something after a hash', () => {
    expect(titleFromUrl('https://notion.so/Launch-plan-8f3a9c21b4de7701')).toBe('Launch plan')
  })

  it('falls back to the host, which at least reads as an address', () => {
    expect(titleFromUrl('https://www.figma.com/')).toBe('figma.com')
  })

  it('returns null for a non-http scheme or nonsense', () => {
    expect(titleFromUrl('file:///tmp/x')).toBeNull()
    expect(titleFromUrl('not a url')).toBeNull()
    expect(titleFromUrl(null)).toBeNull()
  })
})

describe('getting text out of whatever shape a body is stored in', () => {
  it('walks a document body and finds the words', () => {
    const body = {
      type: 'doc',
      content: [
        { type: 'heading', content: [{ type: 'text', text: 'Supplier shortlist' }] },
        { type: 'paragraph', content: [{ type: 'text', text: 'Three candidates remain.' }] }
      ]
    }
    expect(textFromBody(body)).toContain('Supplier shortlist')
    expect(deriveTitle({ body })).toBe('Supplier shortlist')
  })

  it('handles a JSON string body', () => {
    expect(deriveTitle({ body: JSON.stringify({ text: 'Weekly retro actions' }) })).toBe(
      'Weekly retro actions'
    )
  })

  it('skips ids and colours, which are not words', () => {
    const body = { id: 'a3f19c88de7701bb44', color: '#ff00aa', text: 'Real content here' }
    const t = textFromBody(body)
    expect(t).toContain('Real content here')
    expect(t).not.toContain('#ff00aa')
    expect(t).not.toContain('a3f19c88de7701bb44')
  })

  it('cannot throw on an unexpected or cyclic shape', () => {
    // It must degrade, not explode: a body shape changing is a routine event
    // and must never be able to stop start-up.
    const cyclic: Record<string, unknown> = { text: 'ok' }
    cyclic.self = cyclic
    expect(() => textFromBody(cyclic)).not.toThrow()
    expect(() => textFromBody(undefined)).not.toThrow()
    expect(() => textFromBody('plain string')).not.toThrow()
  })

  it('stops early rather than walking a huge document to build 60 characters', () => {
    const huge = { content: Array.from({ length: 50_000 }, (_, i) => ({ text: `row ${i}` })) }
    const t = textFromBody(huge, 500)
    expect(t.length).toBeLessThan(2000)
  })
})

describe('the order of preference, cheapest first', () => {
  it('own text beats body beats filename beats URL', () => {
    expect(
      deriveTitle({
        text: 'From the text',
        body: { text: 'From the body' },
        filename: 'from-the-file.md',
        url: 'https://example.com/from-the-url'
      })
    ).toBe('From the text')

    expect(
      deriveTitle({ body: { text: 'From the body' }, filename: 'f.md', url: 'https://e.com/u' })
    ).toBe('From the body')

    expect(deriveTitle({ filename: 'meeting-notes.md', url: 'https://e.com/u' })).toBe(
      'Meeting notes'
    )
  })

  it('returns null when there is genuinely nothing — the only case worth a model call', () => {
    expect(deriveTitle({})).toBeNull()
    expect(deriveTitle({ text: '', body: {}, filename: '', url: '' })).toBeNull()
  })
})

// ── The backfill: bounded, cheap, and unable to invent ─────────────────────

describe('the start-up backfill', () => {
  const backfill = read('main/titleBackfill.ts')

  it('exhausts the free path before spending a token', () => {
    const derivedAt = backfill.indexOf('deriveTitle({ text: c.text })')
    const modelAt = backfill.indexOf('client.messages.create')
    expect(derivedAt).toBeGreaterThan(-1)
    expect(modelAt).toBeGreaterThan(derivedAt)
  })

  it('uses the cheapest tier THROUGH the router, not a hardcoded id', () => {
    // A hardcoded id escapes both the routing table and the user's model-mode
    // override — and is how the app previously ended up a generation behind.
    expect(backfill).toContain("resolveModel('title_backfill')")
    expect(backfill).not.toMatch(/model:\s*['"]claude-/)
    expect(read('main/ai/modelRouting.ts')).toContain('title_backfill: HAIKU')
  })

  it('caps the cost three ways: items, snippet size and output', () => {
    expect(backfill).toContain('const MAX_AI_ITEMS')
    expect(backfill).toContain('const SNIPPET_CHARS')
    expect(backfill).toContain('max_tokens: MAX_OUTPUT_TOKENS')
    expect(backfill).toContain('needsModel.slice(0, MAX_AI_ITEMS)')
  })

  it('sends ONE batched call, not one per item', () => {
    expect((backfill.match(/messages\.create/g) ?? []).length).toBe(1)
  })

  it('never asks about an item with nothing to go on', () => {
    expect(backfill).toContain('c.text.trim().length >= 12')
  })

  it('records every item it considered, so a launch never pays twice', () => {
    expect(backfill).toContain('CREATE TABLE IF NOT EXISTS title_backfill_log')
    expect(backfill).toContain("noteSeen(c.table, c.id, 'no-content')")
    expect(backfill).toContain('seen.has(')
  })

  it('refuses a placeholder from the MODEL too', () => {
    // The model is held to the same bar as the free path.
    expect(backfill).toContain('if (clean && !isUntitled(clean))')
  })

  it('writes nothing when the reply cannot be parsed', () => {
    // A bad response must not be able to rename anything.
    const catchAt = backfill.indexOf('} catch {\n    // Offline, no credit')
    expect(catchAt).toBeGreaterThan(-1)
    expect(backfill.slice(catchAt)).not.toContain('writeTitle')
  })

  it('can never be the reason the app fails to start', () => {
    expect(backfill).toContain('// A repair pass must never be the reason the app fails to start.')
    const main = read('main/index.ts')
    expect(main).toContain('void runTitleBackfill({ allowModel: backgroundModelAllowed() })')
    expect(main).toContain('.catch((e) => {')
  })

  it('runs after the safety backup, because it rewrites titles', () => {
    // Compared at the CALL sites — the import sits at the top of the file and
    // would make this pass for the wrong reason.
    const main = read('main/index.ts')
    const backupCall = main.indexOf('  autoBackupOnLaunch()')
    const backfillCall = main.indexOf('void runTitleBackfill({ allowModel: backgroundModelAllowed() })')
    expect(backupCall).toBeGreaterThan(-1)
    expect(backfillCall).toBeGreaterThan(-1)
    expect(backupCall).toBeLessThan(backfillCall)
  })

  it('is detached from start-up, not part of it', () => {
    // A repair pass must not be why the window is slow to appear.
    const main = read('main/index.ts')
    expect(main).toContain('}, 12_000)')
  })
})

describe('new items stop arriving untitled', () => {
  it('the desk dialog no longer pre-fills the placeholder as a value', () => {
    // This was the manufacturing line: the field LOOKED filled in, so the
    // empty-title guard below it could never fire.
    const dialog = read('renderer/src/components/MakeTaskDialog.tsx')
    expect(dialog).not.toContain("useState(seedTitle.trim() || 'Untitled desk')")
    expect(dialog).toContain('useState(seedTitle.trim())')
    expect(dialog).toContain('if (!title || isUntitled(title))')
  })

  it('a document names itself from the first save that has content', () => {
    // Demanding a name before there is anything to name would mean titling a
    // blank page. Free and deterministic — no model on this path.
    const docs = read('main/db/documents.ts')
    expect(docs).toContain('if (patch.title === undefined && isUntitled(existing.title))')
    expect(docs).toContain('deriveTitle({ body: patch.body })')
  })

  it('and never overwrites a name the user chose', () => {
    const docs = read('main/db/documents.ts')
    expect(docs).toContain('isUntitled(existing.title)')
    expect(docs).toContain("title: draft.title ?? ''")
    expect(docs).not.toContain("draft.title || 'Untitled'")
  })
})
